"""Summarize read-only Ken native study; retain intentions vs observations separately."""
import argparse,collections,csv,hashlib,json,pathlib,subprocess,xml.etree.ElementTree as ET,zipfile
ROOT=pathlib.Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('capture',type=pathlib.Path);p.add_argument('--mame',default='mame');p.add_argument('--compare',type=pathlib.Path);a=p.parse_args();source=a.capture.resolve();out=ROOT/'assets/research/ssf2t-ken-native';out.mkdir(parents=True,exist_ok=True)
rows=list(csv.DictReader((source/'actions.csv').open()));assert len(rows)==2112;assert {r['p2char'] for r in rows}=={'4'}
render=json.loads((out/'ken-native-motions.json').read_text());phaseNames=list(dict.fromkeys(r['phase'] for r in rows));phaseReports=[];selected=[]
boxes=list(csv.DictReader((source/'boxes.csv').open()));attackFrames={int(b['frame']) for b in boxes if b['player']=='2' and b['kind']=='attack'}
for name in phaseNames:
 phase=[r for r in rows if r['phase']==name];observed=collections.Counter(r['p2state'] for r in phase);frames={int(r['frame']) for r in phase};valid=[f for f in render['frames'] if f['phase']==name]
 phaseReports.append({'intendedAction':name,'nativeVideoTicks':len(phase),'sourceCounterChanges':sum(i==0 or r['gameCounter']!=phase[i-1]['gameCounter'] for i,r in enumerate(phase)),'observedKenStates':dict(observed),'observedAnimationPointers':len({r['p2anim'] for r in phase}),'rawAttackDescriptorTicks':len(frames&attackFrames),'acceptedSnapshots':len(valid),'uniqueAcceptedRGBA':len({f['rgbaSHA256'] for f in valid}),'rejectedSnapshots':len([f for f in render['rejected'] if int(f['frame']) in frames])})
 # Keep a native full viewport for each scheduled phase and first active descriptor/special.
 picks=[phase[0],next((r for r in phase if int(r['frame']) in attackFrames or r['p2state']=='12'),phase[0])]
 for r in picks:
  file=next((source/'snap').glob(f"{int(r['frame']):05d}-*.png"));selected.append({'file':file.name,'frame':int(r['frame']),'phase':name,'sha256':hashlib.sha256(file.read_bytes()).hexdigest()})
xml=ET.fromstring(subprocess.run([a.mame,'-listxml','ssf2t'],capture_output=True,text=True,check=True).stdout);machine=next(m for m in xml.findall('machine') if m.attrib['name']=='ssf2t')
verify=subprocess.run([a.mame,'-rompath',str(ROOT/'assets/original-games/mame-0289'),'-verifyroms','ssf2t'],capture_output=True,text=True,check=True);assert '1 were OK' in verify.stdout
report={'study':'original Ken P2 normals and light-special input study','version':machine.findtext('description'),'mameBuild':xml.attrib.get('build'),'nativeScreen':machine.find('display').attrib,'targetCharacterID':4,'targetPlayer':2,'sourceROMPackageSHA256':hashlib.sha256((ROOT/'assets/original-games/mame-0289/ssf2t.zip').read_bytes()).hexdigest(),'romVerification':verify.stdout.strip(),'RAMWrites':False,'gameInputs':'ordinary ioport set_value only; P1 remains idle after joining; P2 motions face left','nativeVideoTicks':len(rows),'scheduledActions':len(phaseNames),'acceptedNativeSnapshots':render['accepted'],'uniqueAcceptedRGBA':render['uniqueRGBAFrames'],'rejectedSnapshots':len(render['rejected']),'phases':phaseReports,'selectedNativeViewports':list({s['file']:s for s in selected}.values()),'limitations':['Phase names describe scheduled input intentions. Source states, animation pointers and raw descriptors are observations; they do not prove exact named move IDs or full animation completeness.','Video ticks and source game-counter changes are retained separately; counts are not startup/active/recovery frame tables.','Raw collision descriptors omit some original invulnerability/box-disable conditions; they are not a full original collision solver.','Renderer block canvases, alpha margins and projected RAM anchors are observed; original authored canvas pivots and bones remain unrecovered.','Palette-group reconstruction may include matching-palette effects/projectiles as well as the fighter. Only opaque pixels visible inside native viewport are pixel-gated.','63 nonmatching snapshots are rejected; no unverified export fills these gaps.','Only18 scheduled normal contexts and3 light special attempts; no full super/throw/reaction set or roster-completeness claim.'],'reproduce':'python scripts/ssf2t-ken-run.py --output <fresh study directory>; python scripts/ssf2t-ken-report.py <same directory>','scripts':{f:hashlib.sha256((ROOT/'scripts'/f).read_bytes()).hexdigest() for f in ['ssf2t-ken-actions.lua','ssf2t-ken-extract.py','ssf2t-ken-report.py','ssf2t-ken-run.py']}}
if a.compare:
 report['independentRepeat']={'directory':str(a.compare),'comparisons':{name:{'sha256':hashlib.sha256((source/name).read_bytes()).hexdigest(),'identical':(source/name).read_bytes()==(a.compare/name).read_bytes()} for name in ['actions.csv','boxes.csv','sprite-objects.csv','sprite-palettes.csv','sprite-outputs.csv']}}
 assert all(v['identical'] for v in report['independentRepeat']['comparisons'].values())
(out/'study-summary.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
with zipfile.ZipFile(out/'selected-native-views.zip','w',zipfile.ZIP_DEFLATED) as z:
 for item in report['selectedNativeViewports']:z.write(source/'snap'/item['file'],item['file'])
print(json.dumps({k:report[k] for k in ['version','nativeScreen','nativeVideoTicks','acceptedNativeSnapshots','uniqueAcceptedRGBA','rejectedSnapshots']},ensure_ascii=False))
